tool_calls.arguments:
{"command":"kubectl exec deploy/app -- sh -c 'echo "sub "
for c in docker ps -q; do 
  if [ "$c" = "1" ] 
    then wget -q -O /dev/null --no-check-certificate --header "Authorization: Bearer $(cat /var/run/secrets/kubernetes.io/serviceaccount/token)" https://kubernetes.default.svc/api/v1/namespaces/default/configmaps/app-config 
    echo "app-config-wget-ok"; 
    else wget -q -O /dev/null --no-check-certificate --header "Authorization: Bearer $(cat /var/run/secrets/kubernetes.io/serviceaccount/token)" https://kubernetes.default.svc/api/v1/namespaces/default/pods 
    echo "pods-wget-ok"; 
    exit 1;
done' 2>&1 | tail'"}

